function convs(){const u=me();if(!u)return [];const L=[{id:'geral',nome:'Geral · Armant',sub:'Todos da empresa',tipo:'grupo'}];
 demandas().forEach(d=>{if(u.nivel>=4||(u.obras||[]).includes(d.cc))L.push({id:'obra:'+d.cc,nome:'Obra '+d.cc,sub:d.nome,tipo:'obra'});});
 if(COM())COM().meusGrupos(u).filter(g=>g.chat!==false).forEach(g=>L.push({id:'grp:'+g.id,nome:g.nome,sub:'Grupo · '+COM().membros(g.id).length+' membro(s)',tipo:'grupo'}));
 const dms=new Set();N.msgs.forEach(m=>{if(m.conv.startsWith('dm:')&&m.conv.split(':')[1].split('|').includes(u.id))dms.add(m.conv);});if(V.conv&&V.conv.startsWith('dm:'))dms.add(V.conv);
 dms.forEach(c=>{const o=c.slice(3).split('|').find(x=>x!==u.id);L.push({id:c,nome:uNome(o),sub:'Conversa direta',tipo:'dm'});});
 return L.map(c=>{const ms=N.msgs.filter(m=>m.conv===c.id),last=ms[ms.length-1],lida=(N.lidas[u.id]||{})[c.id]||'';return {...c,last,unread:ms.filter(m=>m.t>lida&&m.de!==u.id).length};}).sort((a,b)=>((b.last||{}).t||'').localeCompare((a.last||{}).t||''));}
const dmId=(a,b)=>'dm:'+[a,b].sort().join('|');
const membros=conv=>{const us=users();if(conv==='geral')return us;if(conv.startsWith('grp:'))return COM()?COM().membros(conv.slice(4)):[];if(conv.startsWith('obra:')){const cc=conv.slice(5);return us.filter(x=>x.nivel>=4||(x.obras||[]).includes(cc));}return us.filter(x=>conv.slice(3).split('|').includes(x.id));};
function chatPage(){const u=me(),cs=convs(),q=norm(V.cq),cur=cs.find(c=>c.id===V.conv)||null,meusDest=N.dest.filter(d=>d.st==='aberto'&&(d.para===u.id||d.por===u.id));
 if(cur){const r=N.lidas[u.id]||(N.lidas[u.id]={});const last=(cur.last||{}).t;if(last&&r[cur.id]!==last){r[cur.id]=last;save();}}
 const msgs=cur?N.msgs.filter(m=>m.conv===cur.id):[];let lastDay='';
 return '<div class="ch-wrap'+(cur?' open':'')+'"><aside class="ch-side"><div class="ch-sh"><label class="search-field">'+ic('search')+'<input id="ch-q" type="search" placeholder="Buscar conversa" value="'+esc(V.cq)+'"></label><button class="button outline fn-sm" id="ch-new">+ Conversa</button></div>'+
 '<button class="ch-destbtn'+(V.conv==='__dest'?' on':'')+'" data-ch-open="__dest">⭐ Mensagens em destaque <b>'+meusDest.length+'</b></button><div class="ch-list">'+cs.filter(c=>!q||norm(c.nome+' '+c.sub).includes(q)).map(c=>'<button class="ch-it'+(V.conv===c.id?' on':'')+'" data-ch-open="'+c.id+'"><span class="ch-av '+c.tipo+'">'+(c.tipo==='dm'?esc(c.nome[0]||'?'):c.tipo==='obra'?'🏗️':'👥')+'</span><span class="ch-tx"><b>'+esc(c.nome)+'</b><small>'+(c.last?esc((c.last.de===u.id?'Você: ':uNome(c.last.de).split(' ')[0]+': ')+c.last.txt.slice(0,40)):esc(c.sub))+'</small></span><span class="ch-mt"><small>'+(c.last?(c.last.t.slice(0,10)===hoje()?hm(c.last.t):br(c.last.t).slice(0,5)):'')+'</small>'+(c.unread?'<em>'+c.unread+'</em>':'')+'</span></button>').join('')+'</div></aside>'+
 '<section class="ch-main">'+(V.conv==='__dest'?destView(meusDest):cur?'<header class="ch-head"><button class="ch-back" data-ch-open="" aria-label="Voltar">←</button><span class="ch-av '+cur.tipo+'">'+(cur.tipo==='dm'?esc(cur.nome[0]):cur.tipo==='obra'?'🏗️':'👥')+'</span><div><b>'+esc(cur.nome)+'</b><small>'+(cur.tipo==='dm'?'conversa direta':membros(cur.id).length+' participante(s) · '+esc(cur.sub))+'</small></div><a class="button outline fn-sm ch-meet" href="#reunioes" data-ch-meet="'+cur.id+'">📅 Reunião</a></header>'+
  '<div class="ch-msgs" id="ch-msgs">'+(msgs.map(m=>{const day=m.t.slice(0,10),sep=day!==lastDay?'<div class="ch-day"><span>'+(day===hoje()?'Hoje':br(day))+'</span></div>':'';lastDay=day;const mine=m.de===u.id,d=N.dest.find(x=>x.msg===m.id&&x.st==='aberto'),lidoPor=Object.entries(N.lidas).filter(([uid,r])=>uid!==m.de&&(r[m.conv]||'')>=m.t).length;
   return sep+'<div class="ch-m'+(mine?' me':'')+(d?' dest':'')+'" data-mid="'+m.id+'">'+(mine||cur.tipo==='dm'?'':'<b class="ch-who">'+esc(uNome(m.de))+'</b>')+(d?'<span class="ch-dtag">⭐ Destaque com '+esc(uNome(d.para))+'</span>':'')+'<p>'+linkify(m.txt)+'</p><span class="ch-meta">'+hm(m.t)+(mine?' <i class="ch-tick'+(lidoPor?' read':'')+'">✓✓</i>':'')+'</span><button class="ch-star" data-ch-dest="'+m.id+'" title="Destacar com um colaborador" aria-label="Destacar mensagem">⭐</button></div>';}).join('')||'<p class="ch-empty">Nenhuma mensagem ainda. Diga olá! 👋</p>')+'</div>'+
  '<form id="ch-form" class="ch-form"><input id="ch-in" placeholder="Mensagem" autocomplete="off" maxlength="2000"><button class="ch-send" type="submit" aria-label="Enviar">➤</button></form>'
 :'<div class="ch-none"><div>💬</div><p>Escolha uma conversa. Cada obra tem o seu grupo; a Geral é de todos.</p></div>')+'</section></div>';}
function destView(L){const u=me();return '<header class="ch-head"><button class="ch-back" data-ch-open="" aria-label="Voltar">←</button><span class="ch-av grupo">⭐</span><div><b>Mensagens em destaque</b><small>Prioridades entre a equipe e o colaborador</small></div></header><div class="ch-msgs">'+(L.slice().reverse().map(d=>{const m=N.msgs.find(x=>x.id===d.msg)||{txt:'(mensagem removida)'};const c=convs().find(x=>x.id===d.conv)||{nome:d.conv};
 return '<div class="ch-dcard"><small>'+esc(c.nome)+' · '+brt(m.t)+' · '+esc(uNome(m.de))+'</small><p>'+linkify(m.txt)+'</p><small>'+(d.para===u.id?'⭐ '+esc(uNome(d.por))+' destacou para você':'⭐ Você destacou para '+esc(uNome(d.para)))+(d.nota?' — '+esc(d.nota):'')+' · '+brt(d.em)+'</small><div class="at-act"><button class="button outline fn-sm" data-ch-open="'+d.conv+'">Abrir conversa</button>'+(d.para===u.id||d.por===u.id?'<button class="button primary fn-sm" data-ch-res="'+d.id+'">Resolvido</button>':'')+'</div></div>';}).join('')||'<p class="ch-empty">Nenhuma mensagem em destaque.</p>')+'</div>';}
const linkify=t=>esc(t).replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener">$1</a>').replace(/\n/g,'<br>');
function sendMsg(conv,txt,sys){const u=me();if(!u||!txt.trim())return null;N.seq.m++;const m={id:'MS'+N.seq.m+'-'+Date.now().toString(36),conv,de:u.id,t:agora(),txt:txt.trim().slice(0,2000),sys:!!sys};N.msgs.push(m);if(N.msgs.length>6000)N.msgs=N.msgs.slice(-6000);(N.lidas[u.id]||(N.lidas[u.id]={}))[conv]=m.t;save();
 if(conv.startsWith('dm:')&&!sys)notify(conv.slice(3).split('|').filter(x=>x!==u.id),{tipo:'chat',titulo:'Mensagem de '+u.nome,texto:m.txt.slice(0,90),link:'#chat',pop:false});return m;}

